package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.BusinessSessionProtocol;
import java.math.BigInteger;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.transaction.support.TransactionSynchronizationManager;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.FormalEvaluationCoverageTest.*;
/** Actual composition with explicit current-authority doubles, never provider-send or professional evidence. */
class FormalEvaluationModelPreparationTest {
 final PermissionSchema json=new PermissionSchema();final ModelEligibilityAuthority eligibility=mock(ModelEligibilityAuthority.class);final ModelEligibilityAuthority.Verified model=mock(ModelEligibilityAuthority.Verified.class);final ModelConfigurationService models=mock(ModelConfigurationService.class);final FormalCapabilityIdentityAuthority capabilities=mock(FormalCapabilityIdentityAuthority.class);final FormalCapabilityIdentityAuthority.VerifiedCapability role=mock(FormalCapabilityIdentityAuthority.VerifiedCapability.class);final SourceReadAuthority sources=mock(SourceReadAuthority.class);final ResourceReadAuthority resources=mock(ResourceReadAuthority.class);final RunTokenAuthoritySchema runtime=mock(RunTokenAuthoritySchema.class);
 final EnterpriseAccess.Admission a=mock(EnterpriseAccess.Admission.class);final FormalEvaluationExecutionInputs.Prepared inputs=mock(FormalEvaluationExecutionInputs.Prepared.class);final FormalEvaluationExecutionAdmission.Prepared execution=mock(FormalEvaluationExecutionAdmission.Prepared.class);final FormalEvaluationExecutionScopes.Prepared scope=mock(FormalEvaluationExecutionScopes.Prepared.class);final AgentExecutionPolicyProtocol.Definition policy=mock(AgentExecutionPolicyProtocol.Definition.class);
 final FormalEvaluationModelPreparation service=new FormalEvaluationModelPreparation(eligibility,models,capabilities,sources,resources,runtime,json);
 final FormalEvaluationExecutionProtocol.Node node=new FormalEvaluationCoverageTest().node(20,0,"N01",true);final com.fasterxml.jackson.databind.node.ObjectNode roleScope=json.object();TenantScope tenant;
 final String project=id(94),actor=id(90),tenantId=id(91),sourceId=id(30),sourceVersion=id(31),purpose="DOCUMENT_BODY";
 FormalEvaluationModelPreparationTest()throws Exception{
  when(a.actorId()).thenReturn(actor);when(a.context()).thenReturn(new BusinessSessionProtocol.Context(tenantId,"1","1","1"));when(inputs.requireCurrent(a)).thenReturn(execution);when(execution.nodes()).thenReturn(List.of(node));when(execution.projectId()).thenReturn(project);when(execution.classification()).thenReturn("INTERNAL");when(execution.policy()).thenReturn(policy);
  var binding=new AgentExecutionPolicyProtocol.NodeBinding("N01",node.role(),node.model(),node.tokenizer(),null,json.object(),List.of());when(policy.bindings()).thenReturn(List.of(binding));when(policy.sourceSelection()).thenReturn(new AgentExecutionPolicyProtocol.SourceSelection(b(32),"FIXED_SOURCE_VERSIONS",List.of(b(31))));when(policy.region()).thenReturn("cn");when(policy.environment()).thenReturn("PRODUCTION");when(policy.businessPurpose()).thenReturn(purpose);
  when(scope.snapshot()).thenReturn(b(33));when(scope.manifest()).thenReturn(new TaskProtocol.ScopeSnapshotManifest("1.0.0",tenantId,project,id(33),id(34),null,"1","1",List.of(new TaskProtocol.ScopeSnapshotMember(sourceId,sourceVersion,id(35),id(36),id(37),id(38),id(39),H))));
  when(eligibility.require(a,node.model().version_id(),"RUN_CREATION",project)).thenReturn(model);when(model.contentSha256()).thenReturn(H);when(model.safeReplayBinding()).thenReturn(new ModelEligibilityBinding("1.0.0","deepseek","model","version",node.model().version_id(),id(40),H,id(41),id(42),id(43),id(44),id(45),List.of("INTERNAL"),List.of("cn"),false));
  var definition=new ModelConfigurationProtocol.Definition("deepseek","https://fixture.invalid","cn","model","version",null,id(42),id(43),null,b(44),"USD",null,null,null,null);
  when(models.requireCurrentExternal(a,node.model().version_id(),"RUN_CREATION",project)).thenReturn(new ModelConfigurationProtocol.Fixed("1.0.0",tenantId,project,id(40),node.model().version_id(),null,definition,"fixture",id(46),"1",actor,"2026-10-18T00:00:00Z"));
  when(capabilities.require(a,node.role(),"ROLE",project,"EVALUATION_RESULTS")).thenReturn(role);var roleDoc=json.object();roleDoc.putObject("request").set("tool_scope",roleScope);when(role.canonicalDefinition()).thenReturn(roleDoc);when(role.authorizations()).thenReturn(json.object());when(runtime.read(eq("RoleScope"),anyString())).thenReturn(roleScope);
  var permissions=roleScope.putArray("permissions");for(var permission:List.of(new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(tenantId,project,"CONFIGURATION",id(40)),"model.send","EVALUATION_RESULTS"),new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(tenantId,null,"SOURCE",sourceId),"source.read",purpose),new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(tenantId,null,"SOURCE",sourceId),"source.external.process",purpose),new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(tenantId,project,"PROJECT",project),"project.read",purpose)))permissions.add(json.tree(permission));
  when(sources.require(eq(a),any())).thenReturn(new SourceReadProtocol.VerifiedSource(new SourceReadProtocol.SourceRow(tenantId,sourceId,sourceVersion,null,"ENTERPRISE","INTERNAL",id(39),H,H,null),null,null,null,null,null,null));
 }
 @BeforeEach void open(){tenant=TenantScope.open(new TenantScope.Identity(tenantId,actor,BigInteger.ONE,BigInteger.ONE,BigInteger.ONE));TransactionSynchronizationManager.setActualTransactionActive(true);}
 @AfterEach void close(){TransactionSynchronizationManager.clear();tenant.close();}
 @Test void genuineEvaluationModelPreparationUsesIndependentPermissionsAndFixedSource()throws Exception{var proof=service.require(a,inputs,scope,node);assertEquals(node,proof.node());assertEquals(id(41),proof.model().connection_verification_id());verify(resources).require(a,new PermissionProtocol.Scope(tenantId,project,"CONFIGURATION",id(40)),"model.send","EVALUATION_RESULTS");verify(resources,never()).require(any(),any(),eq("model.verify"),any());verify(sources).require(a,new SourceReadProtocol.ReadRequirement(sourceVersion,id(39),project,id(33),id(35),null,SourceReadProtocol.Use.MODEL_SEND,purpose,"PRODUCTION","cn","deepseek"));assertEquals(4,proof.permissions().size());}
 @Test void modelVerifyCannotReplaceModelSend()throws Exception{when(resources.require(eq(a),any(),eq("model.send"),eq("EVALUATION_RESULTS"))).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));}
 @Test void roleMustIndependentlyPermitExternalProcessing(){((com.fasterxml.jackson.databind.node.ArrayNode)roleScope.get("permissions")).remove(2);assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));}
 @Test void inputCurrentRecheckCannotBeSkipped()throws Exception{when(inputs.requireCurrent(a)).thenThrow(new TenantAccessException(ErrorCode.SCOPE_STALE));assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));verifyNoInteractions(sources);}
 @Test void sourceExternalRightsRevocationRejectsPreparation()throws Exception{when(sources.require(eq(a),any())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));}
 @Test void currentModelHashMustMatchPolicyNode(){when(model.contentSha256()).thenReturn("b".repeat(64));assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));}
 @Test void differentCellCannotReusePreparedScope(){assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,new FormalEvaluationCoverageTest().node(21,0,"N01",true)));}
 @Test void missingSelectedSourceRejected(){when(policy.sourceSelection()).thenReturn(new AgentExecutionPolicyProtocol.SourceSelection(b(32),"FIXED_SOURCE_VERSIONS",List.of(b(31),b(55))));assertThrows(TenantAccessException.class,()->service.require(a,inputs,scope,node));}
 @Test void proofCannotMoveToAnotherAdmission()throws Exception{var proof=service.require(a,inputs,scope,node);assertThrows(TenantAccessException.class,()->proof.requireCurrent(mock(EnterpriseAccess.Admission.class)));}
 @Test void privateProofRechecksRevokedModelSend()throws Exception{var proof=service.require(a,inputs,scope,node);when(resources.require(eq(a),any(),eq("model.send"),eq("EVALUATION_RESULTS"))).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->proof.requireCurrent(a));}
 @Test void privateProofRechecksChangedRoleNarrowing()throws Exception{var proof=service.require(a,inputs,scope,node);((com.fasterxml.jackson.databind.node.ArrayNode)roleScope.get("permissions")).remove(2);assertThrows(TenantAccessException.class,()->proof.requireCurrent(a));}
 @Test void modelPreparationHasNoPublicProofConstructor(){for(var constructor:FormalEvaluationModelPreparation.Prepared.class.getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(constructor.getModifiers()));}

 @Test void actualGrantDatesArePreservedAndRevalidated()throws Exception{var from=java.time.LocalDateTime.of(2026,10,1,0,0);var to=from.plusDays(31);var grant=new PermissionProtocol.GrantRow(id(70),actor,project,"CONFIGURATION",id(40),"model.send","{}","ACTIVE",from,to,id(71),"1.0.0",H,BigInteger.ONE);when(resources.require(eq(a),any(),eq("model.send"),eq("EVALUATION_RESULTS"))).thenReturn(grant);var proof=service.require(a,inputs,scope,node);assertTrue(proof.canonical().contains("2026-10-01T00:00:00"));proof.requireCurrent(a);when(resources.require(eq(a),any(),eq("model.send"),eq("EVALUATION_RESULTS"))).thenReturn(new PermissionProtocol.GrantRow(id(70),actor,project,"CONFIGURATION",id(40),"model.send","{}","ACTIVE",from,to.plusDays(1),id(71),"1.0.0",H,BigInteger.ONE));assertThrows(TenantAccessException.class,()->proof.requireCurrent(a));}
}
